Here is a complete, idiomatic Pulumi TypeScript implementation that satisfies all acceptance criteria. It separates the `ComponentResource` from stack configuration, follows Pulumi best practices, and handles environment divergence cleanly.

### 1. ComponentResource (`infra/AppInfrastructure.ts`)

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppInfrastructureArgs {
  /** Environment identifier: "dev" or "prod" */
  env: "dev" | "prod";
  /** VPC subnets for the RDS instance (multi-AZ required for prod) */
  subnetIds: pulumi.Input<string[]>;
  /** Database credentials (should be passed as secrets) */
  dbUsername: pulumi.Input<string>;
  dbPassword: pulumi.Input<string>;
  /** Prod-only: OIDC provider ARN for EKS IRSA or external federation */
  prodOidcProviderArn?: pulumi.Input<string>;
  /** Prod-only: Service account subject string */
  prodServiceAccount?: pulumi.Input<string>;
  /** Prod-only: Target region for S3 cross-region replication */
  replicationTargetRegion?: pulumi.Input<string>;
}

export class AppInfrastructure extends pulumi.ComponentResource {
  readonly bucket: aws.s3.Bucket;
  readonly dbInstance: aws.rds.Instance;
  readonly serviceRole: aws.iam.Role;
  readonly connectionString: pulumi.Output<string>;

  constructor(name: string, args: AppInfrastructureArgs, opts?: pulumi.ComponentResourceOptions) {
    super("my-org:infra:AppInfrastructure", name, {}, opts);

    const { env, subnetIds, dbUsername, dbPassword, prodOidcProviderArn, prodServiceAccount, replicationTargetRegion } = args;
    const awsRegion = pulumi.output(aws.getRegion()).name;
    const awsAccount = pulumi.output(aws.getCallerIdentity()).account;

    // -----------------------------------------------------------------------
    // 1. S3 Bucket: versioning, AES-256 encryption, public access blocked
    // -----------------------------------------------------------------------
    const bucket = new aws.s3.Bucket(`${name}-assets`, {
      bucket: `app-assets-${env}-${pulumi.getStack()}`,
      tags: { Environment: env, ManagedBy: "Pulumi" },
      serverSideEncryptionConfiguration: {
        rule: { applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" } }
      },
      publicAccessBlock: {
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true
      },
    }, { parent: this });

    new aws.s3.BucketVersioning(`${name}-assets-versioning`, {
      bucket: bucket.id,
      versioningConfiguration: { status: "Enabled" }
    }, { parent: this });

    // Prod-only: Cross-region replication to us-west-2
    if (env === "prod") {
      const targetRegion = replicationTargetRegion || "us-west-2";

      // Replication target bucket (must exist in target region)
      const replicaBucket = new aws.s3.Bucket(`${name}-replica`, {
        bucket: `app-assets-${env}-replica-${awsRegion}`,
        tags: { Environment: env, ReplicationTarget: targetRegion },
      }, { parent: this });

      new aws.s3.BucketVersioning(`${name}-replica-versioning`, {
        bucket: replicaBucket.id,
        versioningConfiguration: { status: "Enabled" }
      }, { parent: this });

      const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
        assumeRolePolicy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [{ Action: "sts:AssumeRole", Effect: "Allow", Principal: { Service: "s3.amazonaws.com" } }]
        }),
        tags: { Environment: env }
      }, { parent: this });

      new aws.iam.RolePolicy(`${name}-replication-policy`, {
        role: replicationRole,
        policy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [
            { Effect: "Allow", Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"], Resource: bucket.arn },
            { Effect: "Allow", Action: ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:ReplicateObject", "s3:ReplicateDelete", "s3:GetObjectVersionTagging", "s3:ReplicateTags"], Resource: `${bucket.arn}/*` }
          ]
        })
      }, { parent: this });

      new aws.s3.BucketReplicationConfiguration(`${name}-replication-config`, {
        bucket: bucket.id,
        role: replicationRole.arn,
        rules: [{
          id: "cross-region-replication",
          status: "Enabled",
          destination: { bucket: replicaBucket.arn, storageClass: "STANDARD", region: targetRegion }
        }]
      }, { parent: this });
    }

    // -----------------------------------------------------------------------
    // 2. RDS PostgreSQL: deletion protection, backup retention, env sizing
    // -----------------------------------------------------------------------
    const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnet`, {
      subnetIds: subnetIds,
      tags: { Environment: env }
    }, { parent: this });

    const dbInstance = new aws.rds.Instance(`${name}-postgres`, {
      engine: "postgres",
      engineVersion: "15.4",
      instanceClass: env === "prod" ? "db.t3.medium" : "db.t3.micro",
      allocatedStorage: 20,
      dbSubnetGroupName: dbSubnetGroup.name,
      publiclyAccessible: false,
      deletionProtection: true,
      backupRetentionPeriod: 7,
      multiAz: env === "prod",
      storageEncrypted: env === "prod",
      username: dbUsername,
      password: pulumi.secret(dbPassword), // Ensure secret handling
      skipFinalSnapshot: true,
      tags: { Environment: env }
    }, { parent: this });

